def h(b):return hashlib.sha256(b).hexdigest()
def load(p):return json.loads(Path(p).read_text(encoding='utf8'))
def canonical(x):return json.dumps(x,ensure_ascii=False,sort_keys=True,separators=(',',':'),allow_nan=False).encode()
def logical(x,key):return h(canonical({k:v for k,v in x.items() if k!=key}))
def seal(x,key):x[key]=h(canonical(x));return x
def write(p,x):Path(p).write_bytes((json.dumps(x,ensure_ascii=False,indent=2,allow_nan=False)+'\n').encode())
def absolute(p):p=Path(p);return p if p.is_absolute() else R/p
